struct Frame{const MissionNetsockStartupBindings& b;U site,size,at;Frame(const MissionNetsockStartupBindings& source,U target,U bytes,const std::vector<U>& args):b(source),site(target),size(bytes),at(0){if(!b.frame||!b.release)throw std::runtime_error("Netsock startup caller frame is not bound");at=b.frame(site,size,args);}~Frame(){b.release(site,at,size);}};
